const cfg = $('Config').first().json;
const d = new Date();
const fim = d.toISOString().slice(0, 10);
const ini = new Date(d.getTime() - Number(cfg.dias_janela ?? 14) * 86400000).toISOString().slice(0, 10);
const modoTeste = Boolean(Number(cfg.modo_teste));
const nfeLimite = Number(cfg.nfe_limite ?? 50);
return [{
  json: {
    ...cfg,
    dataInicial: ini,
    dataFinal: fim,
    dataEmissaoInicial: `${ini} 00:00:00`,
    dataEmissaoFinal: `${fim} 23:59:59`,
    continuar: true,
    modo_teste: modoTeste,
    nfe_limite: modoTeste ? nfeLimite : 0,
    compras_max_paginas: modoTeste ? 1 : Number(cfg.compras_max_paginas ?? 20),
    nfe_max_detalhe: modoTeste ? nfeLimite : Number(cfg.nfe_max_detalhe ?? 400),
    bling_interval_ms: modoTeste
      ? Number(cfg.bling_interval_ms_teste ?? 3500)
      : Number(cfg.bling_interval_ms ?? 4000),
  },
}];

const cfg = $('Continuar sync').first().json;
const maxPag = Number(cfg.compras_max_paginas ?? 20);
const pages = [];

function buildQuery(parts) {
  return parts
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&');
}

for (let p = 1; p <= maxPag; p++) {
  const queryParts = [['pagina', p], ['limite', '100']];
  if (!cfg.modo_teste) {
    queryParts.push(['tipo', String(cfg.nfe_tipo ?? 0)]);
    if (cfg.dataEmissaoInicial) queryParts.push(['dataEmissaoInicial', cfg.dataEmissaoInicial]);
    if (cfg.dataEmissaoFinal) queryParts.push(['dataEmissaoFinal', cfg.dataEmissaoFinal]);
  }
  pages.push({
    json: {
      page: p,
      bling_base_url: cfg.bling_base_url,
      nfe_url: `${cfg.bling_base_url}/nfe?${buildQuery(queryParts)}`,
      dataEmissaoInicial: cfg.dataEmissaoInicial,
      dataEmissaoFinal: cfg.dataEmissaoFinal,
    },
  });
}
return pages;

const cfg = $('Continuar sync').first().json;
const allowed = new Set(String(cfg.nfe_series ?? '').split(',').map((s) => s.trim()).filter(Boolean));
const maxDetalhe = Number(cfg.nfe_max_detalhe ?? 400);
const capNotas = Number(cfg.nfe_limite ?? 0) > 0 ? Number(cfg.nfe_limite) : Infinity;
let notasVistas = 0;
const comItens = [];
const precisaDetalhe = [];
let ignoradasSerie = 0;
let semSerieFilaDetalhe = 0;
let capDetalheIgnoradas = 0;
let nfesListaTotal = 0;
let errosLista = 0;
let paginasComDados = 0;
let erroListaAmostra = null;
let ignoradasTipo = 0;
let ignoradasPeriodo = 0;
const tipoCfg = Number(cfg.nfe_tipo ?? 0);
const iniPeriodo = new Date(String(cfg.dataInicial ?? cfg.dataEmissaoInicial ?? '').slice(0, 10)).getTime();
const fimPeriodo = new Date(String(cfg.dataFinal ?? cfg.dataEmissaoFinal ?? '').slice(0, 10)).getTime();

function captureListaErr(item) {
  const e = item.json.error;
  if (e) {
    if (typeof e === 'string') return e;
    return e.message ?? e.description ?? e.type ?? JSON.stringify(e);
  }
  return JSON.stringify(item.json).slice(0, 400);
}

function isEntrada(n) {
  const t = Number(n.tipo ?? n.tipoNF ?? n.tipoNota ?? 0);
  return t === tipoCfg;
}

function inPeriodo(n) {
  if (!cfg.modo_teste) return true;
  if (Number.isNaN(iniPeriodo) || Number.isNaN(fimPeriodo)) return true;
  const raw = n.dataEmissao ?? n.data ?? n.dataEntrada;
  if (!raw) return true;
  const ms = new Date(String(raw).slice(0, 10)).getTime();
  if (Number.isNaN(ms)) return true;
  return ms >= iniPeriodo && ms <= fimPeriodo + 86400000;
}

function getSerie(n) {
  return String(n.serie ?? n.numeroSerie ?? n.serieNota ?? '').trim();
}

function hasItens(n) {
  const itens = n.itens ?? n.itensNF ?? n.itensNota ?? [];
  return Array.isArray(itens) && itens.length > 0;
}

for (const item of $input.all()) {
  if (item.json.error) {
    errosLista += 1;
    if (!erroListaAmostra) erroListaAmostra = captureListaErr(item);
    continue;
  }
  const batch = item.json.data ?? [];
  if (!Array.isArray(batch)) continue;
  if (batch.length > 0) paginasComDados += 1;
  for (const n of batch) {
    if (notasVistas >= capNotas) break;
    if (!n?.id) continue;
    notasVistas += 1;
    nfesListaTotal += 1;

    if (!isEntrada(n)) {
      ignoradasTipo += 1;
      continue;
    }
    if (!inPeriodo(n)) {
      ignoradasPeriodo += 1;
      continue;
    }

    const serie = getSerie(n);

    if (allowed.size > 0 && serie && !allowed.has(serie)) {
      ignoradasSerie += 1;
      continue;
    }

    if (hasItens(n)) {
      comItens.push({ json: { fromList: true, nfeData: n } });
      continue;
    }

    if (precisaDetalhe.length < maxDetalhe) {
      if (!serie) semSerieFilaDetalhe += 1;
      precisaDetalhe.push({ json: { fromList: false, nfeId: String(n.id), serie: serie || null, bling_base_url: cfg.bling_base_url } });
    } else {
      capDetalheIgnoradas += 1;
    }
  }
  if (notasVistas >= capNotas) break;
}

const stats = {
  modo_teste: Boolean(cfg.modo_teste),
  nfe_limite: capNotas === Infinity ? 0 : capNotas,
  nfes_lista_total: nfesListaTotal,
  paginas_com_dados: paginasComDados,
  erros_lista: errosLista,
  erro_lista_amostra: erroListaAmostra,
  ignoradas_tipo: ignoradasTipo,
  ignoradas_periodo: ignoradasPeriodo,
  com_itens: comItens.length,
  precisa_detalhe: precisaDetalhe.length,
  ignoradas_serie: ignoradasSerie,
  sem_serie_fila_detalhe: semSerieFilaDetalhe,
  cap_detalhe_ignoradas: capDetalheIgnoradas,
  data_inicial: cfg.dataInicial ?? cfg.dataEmissaoInicial,
  data_final: cfg.dataFinal ?? cfg.dataEmissaoFinal,
};

const out = [...comItens, ...precisaDetalhe];
if (out.length === 0) {
  return [{ json: { fromList: true, nfeData: null, stats } }];
}

return out.map((row, idx) => ({
  json: {
    ...row.json,
    stats: idx === 0 ? stats : undefined,
  },
}));

const rows = $input.all().filter((item) => item.json.fromList === false && item.json.nfeId);
if (rows.length === 0) {
  return [{ json: { skip_detalhe: true } }];
}
return rows;

const cfg = $('Continuar sync').first().json;
const COMPANY_ID = cfg.company_id;
const allowedSeries = new Set(String(cfg.nfe_series ?? '').split(',').map((s) => s.trim()).filter(Boolean));
const stats = ($('IDs notas').first().json.stats ?? {});

const rpcRows = [];
let errosApi = 0;
let notasIgnoradasSerie = 0;
let notasProcessadas = 0;
let notasSemItens = 0;
let notasSemChave = 0;
let skippedReturnLocal = 0;
let skippedMarketplaceLocal = 0;
let linhasNfe = 0;
let exemploLinha = null;
let exemploSupplier = null;
let payloadsSemCnpj = 0;
let payloadsComCnpjContato = 0;
let payloadsComCnpjChave = 0;

function resolveNfe(raw) {
  const nfe = raw?.data ?? raw;
  if (nfe?.data?.id) return nfe.data;
  return nfe;
}

function getItens(nfe) {
  const lists = [nfe.itens, nfe.itensNF, nfe.itensNota, nfe.notaFiscal?.itens, nfe.items];
  for (const c of lists) {
    if (Array.isArray(c) && c.length) return c;
  }
  return [];
}

function getQty(linha) {
  return Math.abs(Number(
    linha.quantidade ?? linha.qtd ?? linha.qtde ?? linha.quantidadeComercial ?? linha.qCom ?? 0
  ));
}

function getUnitCost(linha) {
  return Number(
    linha.valorUnitario ?? linha.valor ?? linha.vUnCom ?? linha.preco ?? 0
  );
}

function digits(v) {
  return String(v ?? '').replace(/\D/g, '') || null;
}

function cnpjFromChave(chave) {
  const c = digits(chave);
  if (!c || c.length !== 44) return null;
  // Chave NFe: posições 7-20 (1-based) = CNPJ do emitente
  return c.slice(6, 20);
}

function getSupplier(nfe, chave) {
  const emit = nfe.contato ?? nfe.emitente ?? nfe.fornecedor ?? nfe.fornecedorNota ?? {};
  const nested = emit.contato ?? {};
  const fromContato = digits(
    emit.numeroDocumento ?? emit.cnpj ?? emit.cpfCnpj ?? emit.documento ??
    nested.numeroDocumento ?? nested.cnpj ?? nested.cpfCnpj ?? nested.documento ??
    nfe.numeroDocumentoEmitente ?? nfe.cnpjEmitente
  );
  const doc = fromContato || cnpjFromChave(chave);
  const name = emit.nome ?? emit.razaoSocial ?? emit.xNome ?? nested.nome ?? nested.razaoSocial ?? null;
  return {
    document: doc,
    name,
    document_source: doc ? (fromContato ? 'contato' : 'chave') : null,
  };
}

function isReturnPayload(payload) {
  const nat = String(payload.natureza ?? '').toLowerCase();
  if (nat.includes('devolu') || nat.includes('retorno')) return true;
  const cfops = String(payload.cfops ?? '').toLowerCase();
  if (/\b(1201|1202|2201|2202|1410|2410)\b/.test(cfops)) return true;
  return false;
}

function isMarketplacePayload(payload) {
  const doc = String(payload.supplier?.document ?? '').replace(/\D/g, '');
  if (doc.startsWith('03007331')) return true;
  const name = String(payload.supplier?.name ?? '').toLowerCase();
  if (name.includes('ebazar') || name.includes('mercado livre')) return true;
  return false;
}

function buildPayload(nfeData) {
  const chave = String(nfeData.chaveAcesso ?? nfeData.chave ?? '').replace(/\D/g, '');
  const rawItens = getItens(nfeData);
  const items = rawItens.map((it, idx) => {
    linhasNfe += 1;
    if (!exemploLinha) exemploLinha = JSON.stringify(it).slice(0, 320);
    const codigo = it.codigo ?? it.codigoProduto?.codigo ?? it.produto?.codigo ?? null;
    return {
      line_key: String(it.numeroItem ?? it.nItem ?? idx + 1),
      gtin: it.gtin || it.codigoBarras || it.codigoDeBarras || it.cEAN || null,
      supplier_product_code: codigo,
      sku: codigo,
      name: it.descricao || it.nome || it.xProd || null,
      quantity: getQty(it),
      unit_cost: getUnitCost(it),
    };
  });
  const cfops = [...new Set(rawItens.map((it) => it.cfop ?? it.CFOP).filter(Boolean))].join(',');
  const supplier = getSupplier(nfeData, chave);
  return {
    external_id: chave,
    invoice_number: String(nfeData.numero ?? ''),
    invoice_series: String(nfeData.serie ?? nfeData.numeroSerie ?? ''),
    issued_at: String(nfeData.dataEmissao ?? nfeData.data ?? nfeData.dataEntrada ?? '').slice(0, 10),
    natureza: nfeData.naturezaOperacao || nfeData.natureza || '',
    cfops,
    supplier,
    items,
  };
}

function processNfe(rawNfe) {
  const nfeData = resolveNfe(rawNfe);
  if (!nfeData?.id) return;
  const serie = String(nfeData.serie ?? nfeData.numeroSerie ?? nfeData.serieNota ?? '').trim();
  if (allowedSeries.size > 0 && serie && !allowedSeries.has(serie)) {
    notasIgnoradasSerie += 1;
    return;
  }
  const itens = getItens(nfeData);
  if (!itens.length) {
    notasSemItens += 1;
    return;
  }
  const payload = buildPayload(nfeData);
  if (!payload.external_id || payload.external_id.length !== 44) {
    notasSemChave += 1;
    return;
  }
  if (isReturnPayload(payload)) {
    skippedReturnLocal += 1;
    return;
  }
  if (isMarketplacePayload(payload)) {
    skippedMarketplaceLocal += 1;
    return;
  }
  if (!payload.supplier?.document) payloadsSemCnpj += 1;
  else if (payload.supplier.document_source === 'chave') payloadsComCnpjChave += 1;
  else payloadsComCnpjContato += 1;
  if (!exemploSupplier) {
    exemploSupplier = JSON.stringify({
      document: payload.supplier?.document ?? null,
      name: payload.supplier?.name ?? null,
      document_source: payload.supplier?.document_source ?? null,
      invoice_number: payload.invoice_number,
    }).slice(0, 320);
  }
  // RPC só precisa de document/name
  const rpcSupplier = {
    document: payload.supplier?.document ?? null,
    name: payload.supplier?.name ?? null,
  };
  notasProcessadas += 1;
  rpcRows.push({
    json: {
      company_id: COMPANY_ID,
      payload: { ...payload, supplier: rpcSupplier },
      supabase_url: cfg.supabase_url,
      nfe_id: String(nfeData.id),
      chave: payload.external_id,
    },
  });
}

for (const item of $('IDs notas').all()) {
  if (item.json.fromList === true && item.json.nfeData) {
    processNfe(item.json.nfeData);
  }
}

let detalhes = [];
try {
  detalhes = $('BLING - Detalhe NFe').all();
} catch (e) {
  detalhes = [];
}

for (const item of detalhes) {
  if (item.json.error) {
    errosApi += 1;
    continue;
  }
  processNfe(item.json);
}

const meta = {
  notas_processadas: notasProcessadas,
  notas_sem_itens: notasSemItens,
  notas_sem_chave: notasSemChave,
  skipped_return_local: skippedReturnLocal,
  skipped_marketplace_local: skippedMarketplaceLocal,
  linhas_nfe: linhasNfe,
  exemplo_linha_nfe: exemploLinha,
  exemplo_supplier: exemploSupplier,
  payloads_sem_cnpj: payloadsSemCnpj,
  payloads_cnpj_contato: payloadsComCnpjContato,
  payloads_cnpj_chave: payloadsComCnpjChave,
  notas_lista_com_itens: stats.com_itens ?? 0,
  notas_detalhe_bling: stats.precisa_detalhe ?? 0,
  notas_ignoradas_serie: (stats.ignoradas_serie ?? 0) + notasIgnoradasSerie,
  notas_sem_serie_lista: stats.sem_serie_fila_detalhe ?? 0,
  nfes_lista_total: stats.nfes_lista_total ?? 0,
  paginas_com_dados: stats.paginas_com_dados ?? 0,
  erros_lista: stats.erros_lista ?? 0,
  erro_lista_amostra: stats.erro_lista_amostra ?? null,
  cap_detalhe_ignoradas: stats.cap_detalhe_ignoradas ?? 0,
  data_inicial: stats.data_inicial ?? cfg.dataInicial ?? null,
  data_final: stats.data_final ?? cfg.dataFinal ?? null,
  modo_teste: stats.modo_teste ?? false,
  nfe_limite: stats.nfe_limite ?? 0,
  erros_api: errosApi,
  supabase_url: cfg.supabase_url,
  skip_post: rpcRows.length === 0,
  rpc_total: rpcRows.length,
};

if (rpcRows.length === 0) {
  return [{ json: { ...meta } }];
}

return rpcRows.map((row, idx) => ({
  json: {
    ...row.json,
    ...(idx === 0 ? meta : {}),
  },
}));

const montar = $('Montar payloads RPC').first().json;
let posts = [];
if (!montar.skip_post) {
  try {
    posts = $('Supabase - RPC import_purchase_nfe').all();
  } catch (e) {
    posts = [];
  }
}

let confirmed = 0;
let draft = 0;
let skipped_duplicate = 0;
let rejected_return = Number(montar.skipped_return_local ?? 0);
let rejected_marketplace = Number(montar.skipped_marketplace_local ?? 0);
let error = Number(montar.notas_sem_chave ?? 0);
let postsOk = 0;
let postsFail = 0;
const erros = [];

function formatErr(body) {
  if (!body) return 'sem body';
  if (typeof body === 'string') return body;
  if (body.message) return body.message;
  if (body.error) return body.error;
  if (body.code && body.details) return `${body.code}: ${body.details}`;
  return JSON.stringify(body);
}

function parseRpcResult(item) {
  const j = item.json;
  let body = j.body ?? j;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) {}
  }
  if (Array.isArray(body) && body.length === 1) body = body[0];
  return {
    statusCode: Number(j.statusCode ?? j.status ?? 0),
    result: body,
    chave: item.json.chave ?? null,
  };
}

if (!montar.skip_post) {
  for (const item of posts) {
    const { statusCode, result } = parseRpcResult(item);
    if (statusCode >= 200 && statusCode < 300) {
      postsOk += 1;
      const st = result?.status ?? 'error';
      switch (st) {
        case 'confirmed': confirmed += 1; break;
        case 'draft': draft += 1; break;
        case 'skipped_duplicate': skipped_duplicate += 1; break;
        case 'rejected_marketplace':
      rejected_marketplace += 1;
      break;
    case 'rejected_return': rejected_return += 1; break;
        default:
          error += 1;
          erros.push(formatErr(result).slice(0, 400));
      }
      continue;
    }
    postsFail += 1;
    error += 1;
    erros.push(`${statusCode}: ${formatErr(result).slice(0, 400)}`);
  }
}

return [{
  json: {
    confirmed,
    draft,
    skipped_duplicate,
    rejected_return,
    rejected_marketplace,
    error,
    rpc_total: montar.rpc_total ?? 0,
    notas_processadas: montar.notas_processadas ?? 0,
    notas_sem_itens: montar.notas_sem_itens ?? 0,
    notas_sem_chave: montar.notas_sem_chave ?? 0,
    skipped_return_local: montar.skipped_return_local ?? 0,
    skipped_marketplace_local: montar.skipped_marketplace_local ?? 0,
    linhas_nfe: montar.linhas_nfe ?? 0,
    exemplo_linha_nfe: montar.exemplo_linha_nfe ?? null,
    notas_lista_com_itens: montar.notas_lista_com_itens ?? 0,
    notas_detalhe_bling: montar.notas_detalhe_bling ?? 0,
    notas_ignoradas_serie: montar.notas_ignoradas_serie ?? 0,
    notas_sem_serie_fila_detalhe: montar.notas_sem_serie_lista ?? 0,
    nfes_lista_total: montar.nfes_lista_total ?? 0,
    paginas_com_dados: montar.paginas_com_dados ?? 0,
    erros_lista: montar.erros_lista ?? 0,
    cap_detalhe_ignoradas: montar.cap_detalhe_ignoradas ?? 0,
    data_inicial: montar.data_inicial ?? null,
    data_final: montar.data_final ?? null,
    modo_teste: montar.modo_teste ?? false,
    nfe_limite: montar.nfe_limite ?? 0,
    erro_lista_amostra: montar.erro_lista_amostra ?? null,
    erros_api: montar.erros_api ?? 0,
    posts_ok: postsOk,
    posts_fail: postsFail,
    erro_rpc_amostra: montar.skip_post ? 'nenhuma NF-e para importar' : (erros.slice(0, 3).join(' | ') || null),
  },
}];
